	site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE,
	date TEXT NOT NULL,
	clicks INTEGER NOT NULL,
	impressions INTEGER NOT NULL,
	position REAL NOT NULL,
	PRIMARY KEY (site_id, date)
) WITHOUT ROWID;
